def search_google_scholar_key_words(query, num_results=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0128000" if __import__("os").path.isdir("./environment_mix/0128000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    tool_name = "search_google_scholar_key_words"

    # Ambient auth: pick an active key that can serve the call.
    api_keys = _load("api_keys.json")
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day_start(dt):
        return datetime.datetime(dt.year, dt.month, dt.day)

    def _reset_window_if_needed(krow):
        dws = _parse_dt(krow.get("daily_window_start_at"))
        if dws is None:
            krow["daily_window_start_at"] = _utc_day_start(now).isoformat() + "Z"
            krow["daily_requests_used"] = 0
            return
        if dws < _utc_day_start(now):
            krow["daily_window_start_at"] = _utc_day_start(now).isoformat() + "Z"
            krow["daily_requests_used"] = 0

    active_candidates = []
    for k in api_keys:
        if k.get("status") == "active":
            active_candidates.append(k)
    if not active_candidates:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    # Validate inputs first (but without consuming quota).
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string.")
    q = query.strip()
    if not q:
        return _err("VALIDATION_ERROR", "query must not be empty.")
    if num_results is None:
        num_results = 5000
    if not isinstance(num_results, int):
        return _err("VALIDATION_ERROR", "num_results must be an integer.")

    # Choose key that can satisfy num_results constraints and quota.
    chosen = None
    for k in active_candidates:
        _reset_window_if_needed(k)
        limit = k.get("daily_request_limit")
        used = k.get("daily_requests_used")
        max_per = k.get("max_num_results_per_query")
        if not isinstance(limit, int) or limit < 0:
            continue
        if not isinstance(used, int) or used < 0:
            continue
        if not isinstance(max_per, int) or max_per < 1 or max_per > 50000:
            continue
        if num_results < 1 or num_results > min(50000, max_per):
            continue
        if used + 1 > limit:
            continue
        chosen = k
        break

    # If none could serve due to constraints/quota: determine best error.
    if chosen is None:
        # Check if any active key could satisfy num_results range.
        any_range_ok = False
        any_quota_ok = False
        for k in active_candidates:
            _reset_window_if_needed(k)
            max_per = k.get("max_num_results_per_query")
            if isinstance(max_per, int) and 1 <= max_per <= 50000:
                if 1 <= num_results <= min(50000, max_per):
                    any_range_ok = True
                    limit = k.get("daily_request_limit")
                    used = k.get("daily_requests_used")
                    if isinstance(limit, int) and isinstance(used, int) and used + 1 <= limit:
                        any_quota_ok = True
                        break
        if not any_range_ok:
            # Use first active for message context
            max_per = active_candidates[0].get("max_num_results_per_query")
            upper = None
            if isinstance(max_per, int):
                upper = min(50000, max_per)
            return _err("VALIDATION_ERROR", "num_results is outside the allowed range for this API key.", min_allowed=1, max_allowed=upper)
        if not any_quota_ok:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded for all available active API keys.")
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    # Consume quota atomically and log request regardless of later content results.
    chosen["daily_requests_used"] = int(chosen.get("daily_requests_used", 0)) + 1
    chosen["last_used_at"] = now_iso
    chosen["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # Create search_request row with queued status.
    search_requests = _load("search_requests.json")
    sr_id = "sr_" + uuid.uuid4().hex
    sr = {
        "id": sr_id,
        "api_key_id": chosen["id"],
        "tool_name": tool_name,
        "query": q,
        "author": None,
        "year_start": None,
        "year_end": None,
        "year_range_raw": None,
        "num_results_requested": num_results,
        "num_results_returned": 0,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "source": "google_scholar",
        "requested_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(sr)
    _save("search_requests.json", search_requests)

    # No upstream worker in offline mode. Mark succeeded with existing persisted results if any.
    # Transition queued -> running -> succeeded
    sr["status"] = "running"
    sr["started_at"] = now_iso
    sr["updated_at"] = now_iso

    search_results = _load("search_results.json")
    publications = _load("publications.json")

    pub_by_id = {p.get("id"): p for p in publications if isinstance(p, dict) and p.get("id")}

    # Gather any previously stored results that match this exact request id (none usually).
    # Since this is a new request, no results exist yet; return empty list but still succeed.
    rows = [r for r in search_results if r.get("search_request_id") == sr_id]
    rows.sort(key=lambda r: r.get("rank", 10**9))

    # Enforce uniqueness constraints within request (defensive).
    seen_rank = set()
    seen_pub = set()
    deduped_rows = []
    for r in rows:
        rk = r.get("rank")
        pid = r.get("publication_id")
        if rk in seen_rank or pid in seen_pub:
            continue
        seen_rank.add(rk)
        seen_pub.add(pid)
        deduped_rows.append(r)
    rows = deduped_rows

    # Build results list up to num_results.
    out = []
    for r in rows[:num_results]:
        p = pub_by_id.get(r.get("publication_id"))
        if not p:
            continue
        # Follow merge pointer if publication is merged
        if p.get("status") == "merged" and p.get("merged_into_publication_id"):
            p2 = pub_by_id.get(p.get("merged_into_publication_id"))
            if p2:
                p = p2
        out.append({
            "publication_id": p.get("id"),
            "scholar_cluster_id": p.get("scholar_cluster_id"),
            "title": p.get("title"),
            "authors": p.get("authors_text"),
            "venue": p.get("venue"),
            "year": p.get("publication_year"),
            "citations": p.get("cited_by_count"),
            "url": p.get("url"),
            "pdf_url": p.get("pdf_url"),
            "snippet": r.get("snippet") if r.get("snippet") is not None else p.get("abstract_snippet"),
            "rank": r.get("rank"),
            "result_type": r.get("result_type"),
        })

    sr["num_results_returned"] = len(out)
    sr["status"] = "succeeded"
    sr["finished_at"] = now_iso
    sr["updated_at"] = now_iso
    _save("search_requests.json", search_requests)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "search_request": sr,
        "results": out,
        "meta": {
            "num_results_requested": num_results,
            "num_results_returned": len(out),
            "latency_ms": latency_ms,
        }
    }

