def get_author_info(author_name, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0128000" if __import__("os").path.isdir("./environment_mix/0128000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Ambient auth: require some active api key and enforce quota
    api_keys = _load("api_keys.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day_start(dt):
        return datetime.datetime(dt.year, dt.month, dt.day)

    def _reset_window_if_needed(krow):
        dws = _parse_dt(krow.get("daily_window_start_at"))
        if dws is None:
            krow["daily_window_start_at"] = _utc_day_start(now).isoformat() + "Z"
            krow["daily_requests_used"] = 0
            return
        if dws < _utc_day_start(now):
            krow["daily_window_start_at"] = _utc_day_start(now).isoformat() + "Z"
            krow["daily_requests_used"] = 0

    active = [k for k in api_keys if k.get("status") == "active"]
    if not active:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    if not isinstance(author_name, str):
        return _err("VALIDATION_ERROR", "author_name must be a string.")
    name = author_name.strip()
    if not name:
        return _err("VALIDATION_ERROR", "author_name must not be empty.")

    def _norm_name(s):
        s = s.strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    normalized = _norm_name(name)

    # Choose a key with remaining quota
    chosen = None
    for k in active:
        _reset_window_if_needed(k)
        limit = k.get("daily_request_limit")
        used = k.get("daily_requests_used")
        if isinstance(limit, int) and isinstance(used, int) and limit >= 0 and used >= 0 and used + 1 <= limit:
            chosen = k
            break

    if chosen is None:
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded for all available active API keys.")

    # Consume quota
    chosen["daily_requests_used"] = int(chosen.get("daily_requests_used", 0)) + 1
    chosen["last_used_at"] = now_iso
    chosen["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    author_profiles = _load("author_profiles.json")
    author_publications = _load("author_publications.json")
    publications = _load("publications.json")

    # Resolve by normalized_name exact match
    profile = None
    for ap in author_profiles:
        if ap.get("normalized_name") == normalized:
            profile = ap
            break

    # Offline "fetch outcome" simulation: if profile doesn't exist, create not_found by default.
    created = False
    if profile is None:
        # Ensure unique(normalized_name)
        ap_id = "ap_" + uuid.uuid4().hex
        profile = {
            "id": ap_id,
            "display_name": name,
            "normalized_name": normalized,
            "scholar_author_id": None,
            "affiliation": None,
            "email_domain": None,
            "interests": None,
            "cited_by_total": 0,
            "h_index": 0,
            "i10_index": 0,
            "status": "not_found",
            "last_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        author_profiles.append(profile)
        created = True
    else:
        # Refresh minimal timestamps; do not change status/last_fetched_at without a "successful fetch".
        profile["updated_at"] = now_iso

    # Clamp non-negative counters
    for fld in ("cited_by_total", "h_index", "i10_index"):
        v = profile.get(fld)
        if not isinstance(v, int) or v < 0:
            profile[fld] = 0
            profile["updated_at"] = now_iso

    _save("author_profiles.json", author_profiles)

    # Return associated publications currently on record
    pub_by_id = {p.get("id"): p for p in publications if isinstance(p, dict) and p.get("id")}
    joins = [j for j in author_publications if j.get("author_profile_id") == profile.get("id")]
    joins.sort(key=lambda j: (j.get("sort_order") is None, j.get("sort_order", 10**9), j.get("added_at") or "", j.get("id") or ""))

    pubs_out = []
    for j in joins:
        p = pub_by_id.get(j.get("publication_id"))
        if not p:
            continue
        if p.get("status") == "merged" and p.get("merged_into_publication_id"):
            p2 = pub_by_id.get(p.get("merged_into_publication_id"))
            if p2:
                p = p2
        pubs_out.append({
            "publication_id": p.get("id"),
            "scholar_cluster_id": p.get("scholar_cluster_id"),
            "title": p.get("title"),
            "authors": p.get("authors_text"),
            "venue": p.get("venue"),
            "year": p.get("publication_year"),
            "citations": p.get("cited_by_count"),
            "url": p.get("url"),
            "pdf_url": p.get("pdf_url"),
            "added_at": j.get("added_at"),
            "sort_order": j.get("sort_order"),
            "authorship_position": j.get("authorship_position"),
            "is_corresponding": j.get("is_corresponding"),
        })

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "author_profile": profile,
        "publications": pubs_out,
        "meta": {
            "created": created,
            "num_publications": len(pubs_out),
            "latency_ms": latency_ms,
        }
    }

