    now_iso = now.isoformat() + "Z"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    api_keys = _load("api_keys.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day_start(dt):
        return datetime.datetime(dt.year, dt.month, dt.day)

    # Authenticate: match by id OR client-visible value stored in row (no plaintext check against hash).
    # Because the store only has key_hash, allow id match as the credential.
    krow = None
    token = api_key.strip()
    for k in api_keys:
        if k.get("id") == token or k.get("key_hash") == token:
            krow = k
            break

    if krow is None:
        return _err("UNAUTHORIZED", "Missing or invalid API key.")

    if krow.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", status=krow.get("status"))

    # Reset daily window if needed
    dws = _parse_dt(krow.get("daily_window_start_at"))
    if dws is None or dws < _utc_day_start(now):
        krow["daily_window_start_at"] = _utc_day_start(now).isoformat() + "Z"
        krow["daily_requests_used"] = 0
        krow["updated_at"] = now_iso
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "api_key": {
            "id": krow.get("id"),
            "label": krow.get("label"),
            "status": krow.get("status"),
            "daily_request_limit": krow.get("daily_request_limit"),
            "daily_requests_used": krow.get("daily_requests_used"),
            "daily_window_start_at": krow.get("daily_window_start_at"),
            "max_num_results_per_query": krow.get("max_num_results_per_query"),
            "last_used_at": krow.get("last_used_at"),
            "created_at": krow.get("created_at"),
            "updated_at": krow.get("updated_at"),
        },
        "meta": {
            "latency_ms": latency_ms
        }
    }

def list_search_requests(api_key, status=None, tool_name=None, query_contains=None, author_contains=None, requested_after=None, requested_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0128000" if __import__("os").path.isdir("./environment_mix/0128000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        try:
            if t.endswith("Z"):
                return datetime.datetime.fromisoformat(t[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _start_of_utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _b64e(o):
        raw = json.dumps(o, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        pad = "=" * (-len(s) % 4)
        raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
        return json.loads(raw.decode("utf-8"))

    def _find_active_key(keys, provided):
        if not isinstance(provided, str) or not provided.strip():
            return None
        p = provided.strip()
        for k in keys:
            if k.get("status") != "active":
                continue
            if k.get("id") == p or k.get("key_hash") == p:
                return k
        return None

    def _record_usage(keys, key_row, accepted, endpoint, start_ts, status_code):
        # Persist last_used_at, updated_at and daily usage for accepted calls only.
        # Always log to search_requests as the audit/usage collection for this service.
        reqs = _load("search_requests.json")
        now = _now_utc()
        latency_ms = int((time.time() - start_ts) * 1000)

        # write an audit row for every call
        audit_id = "sr_audit_" + str(int(now.timestamp() * 1000))
        # Ensure uniqueness even if called multiple times within same ms
        existing_ids = {r.get("id") for r in reqs if isinstance(r, dict)}
        if audit_id in existing_ids:
            audit_id = audit_id + "_" + str(len(existing_ids) + 1)

        audit_row = {
            "id": audit_id,
            "api_key_id": key_row.get("id") if isinstance(key_row, dict) else None,
            "tool_name": endpoint,
            "query": "__audit__",
            "author": None,
            "year_start": None,
            "year_end": None,
            "year_range_raw": None,
            "num_results_requested": 1,
            "num_results_returned": 0,
            "status": "failed" if not accepted else "succeeded",
            "error_code": None if accepted else status_code,
            "error_message": None if accepted else "Request rejected",
            "source": "google_scholar",
            "requested_at": _iso(now),
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "latency_ms": latency_ms,
            "is_audit": True,
        }
        reqs.append(audit_row)
        _save("search_requests.json", reqs)

        if accepted:
            key_row["daily_requests_used"] = int(key_row.get("daily_requests_used") or 0)
            key_row["last_used_at"] = _iso(now)
            key_row["updated_at"] = _iso(now)
            # persist key row update
            for i, kk in enumerate(keys):
                if kk.get("id") == key_row.get("id"):
                    keys[i] = key_row
                    break
            _save("api_keys.json", keys)

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled", "partial"}
    allowed_tool = {"search_google_scholar_key_words", "search_google_scholar_advanced"}

    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(list(allowed_status)))
    if tool_name is not None and tool_name not in allowed_tool:
        return _err("VALIDATION_ERROR", "Invalid tool_name", allowed=sorted(list(allowed_tool)))

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    if query_contains is not None and not isinstance(query_contains, str):
        return _err("VALIDATION_ERROR", "query_contains must be a string")
    if author_contains is not None and not isinstance(author_contains, str):
        return _err("VALIDATION_ERROR", "author_contains must be a string")

    ra = _parse_rfc3339(requested_after)
    if requested_after is not None and ra is None:
        return _err("VALIDATION_ERROR", "requested_after must be RFC3339 date-time")
    rb = _parse_rfc3339(requested_before)
    if requested_before is not None and rb is None:
        return _err("VALIDATION_ERROR", "requested_before must be RFC3339 date-time")
    if ra and rb and ra > rb:
        return _err("VALIDATION_ERROR", "requested_after must be <= requested_before")

    # Authenticate + quota check
    keys = _load("api_keys.json")
    key_row = _find_active_key(keys, api_key)
    if key_row is None:
        # no audit possible without a key; refuse
        return _err("UNAUTHORIZED", "Invalid API key or key not active")

    now = _now_utc()
    day0 = _start_of_utc_day(now)
    window_start = _parse_rfc3339(key_row.get("daily_window_start_at")) if isinstance(key_row.get("daily_window_start_at"), str) else None
    if window_start is None:
        window_start = day0
        key_row["daily_window_start_at"] = _iso(day0)
        key_row["daily_requests_used"] = int(key_row.get("daily_requests_used") or 0)
        key_row["updated_at"] = _iso(now)
        for i, kk in enumerate(keys):
            if kk.get("id") == key_row.get("id"):
                keys[i] = key_row
                break
        _save("api_keys.json", keys)
    else:
        if _start_of_utc_day(window_start) < day0:
            key_row["daily_window_start_at"] = _iso(day0)
            key_row["daily_requests_used"] = 0
            key_row["updated_at"] = _iso(now)
            for i, kk in enumerate(keys):
                if kk.get("id") == key_row.get("id"):
                    keys[i] = key_row
                    break
            _save("api_keys.json", keys)

    used = int(key_row.get("daily_requests_used") or 0)
    limit = int(key_row.get("daily_request_limit") or 0)
    if used + 1 > limit:
        _record_usage(keys, key_row, False, "list_search_requests", t0, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_requests_used=used)

    # Accept: increment quota atomically (best-effort in single-process)
    key_row["daily_requests_used"] = used + 1
    key_row["updated_at"] = _iso(now)
    for i, kk in enumerate(keys):
        if kk.get("id") == key_row.get("id"):
            keys[i] = key_row
            break
    _save("api_keys.json", keys)

    # Fetch and filter
    reqs = _load("search_requests.json")
    owned = [r for r in reqs if isinstance(r, dict) and not r.get("is_audit") and r.get("api_key_id") == key_row.get("id")]

    def _req_dt(r):
        dt = _parse_rfc3339(r.get("requested_at")) if isinstance(r.get("requested_at"), str) else None
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    if status is not None:
        owned = [r for r in owned if r.get("status") == status]
    if tool_name is not None:
        owned = [r for r in owned if r.get("tool_name") == tool_name]
    if query_contains:
        q = query_contains.lower()
        owned = [r for r in owned if isinstance(r.get("query"), str) and q in r.get("query").lower()]
    if author_contains:
        a = author_contains.lower()
        owned = [r for r in owned if isinstance(r.get("author"), str) and a in r.get("author").lower()]
    if ra:
        owned = [r for r in owned if _req_dt(r) >= ra]
    if rb:
        owned = [r for r in owned if _req_dt(r) <= rb]

    # Newest first
    owned.sort(key=lambda r: (_req_dt(r), r.get("id") or ""), reverse=True)

    start_index = 0
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token.strip():
            _record_usage(keys, key_row, True, "list_search_requests", t0, "OK")
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")
        tok = None
        try:
            tok = _b64d(page_token.strip())
        except Exception:
            _record_usage(keys, key_row, True, "list_search_requests", t0, "OK")
            return _err("VALIDATION_ERROR", "Invalid page_token")
        if not isinstance(tok, dict) or tok.get("v") != 1 or tok.get("i") is None:
            _record_usage(keys, key_row, True, "list_search_requests", t0, "OK")
            return _err("VALIDATION_ERROR", "Invalid page_token payload")
        if not isinstance(tok.get("i"), int) or tok["i"] < 0:
            _record_usage(keys, key_row, True, "list_search_requests", t0, "OK")
            return _err("VALIDATION_ERROR", "Invalid page_token index")
        start_index = tok["i"]

    total = len(owned)
    items = owned[start_index:start_index + page_size]
    next_i = start_index + len(items)
    has_more = next_i < total
    next_token = _b64e({"v": 1, "i": next_i}) if has_more else None

    _record_usage(keys, key_row, True, "list_search_requests", t0, "OK")
    return {
        "data": items,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
        },
    }

