    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        try:
            if t.endswith("Z"):
                return datetime.datetime.fromisoformat(t[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _start_of_utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _find_active_key(keys, provided):
        if not isinstance(provided, str) or not provided.strip():
            return None
        p = provided.strip()
        for k in keys:
            if k.get("status") != "active":
                continue
            if k.get("id") == p or k.get("key_hash") == p:
                return k
        return None

    def _audit_call(key_row, accepted, endpoint, start_ts, status_code):
        reqs = _load("search_requests.json")
        now = _now_utc()
        latency_ms = int((time.time() - start_ts) * 1000)
        audit_id = "sr_audit_" + str(int(now.timestamp() * 1000))
        existing_ids = {r.get("id") for r in reqs if isinstance(r, dict)}
        if audit_id in existing_ids:
            audit_id = audit_id + "_" + str(len(existing_ids) + 1)
        reqs.append({
            "id": audit_id,
            "api_key_id": key_row.get("id") if isinstance(key_row, dict) else None,
            "tool_name": endpoint,
            "query": "__audit__",
            "author": None,
            "year_start": None,
            "year_end": None,
            "year_range_raw": None,
            "num_results_requested": 1,
            "num_results_returned": 0,
            "status": "failed" if not accepted else "succeeded",
            "error_code": None if accepted else status_code,
            "error_message": None if accepted else "Request rejected",
            "source": "google_scholar",
            "requested_at": _iso(now),
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "latency_ms": latency_ms,
            "is_audit": True,
        })
        _save("search_requests.json", reqs)

    t0 = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id is required and must be a non-empty string")

    keys = _load("api_keys.json")
    key_row = _find_active_key(keys, api_key)
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key or key not active")

    # Quota window reset + quota consume (reads also count)
    now = _now_utc()
    day0 = _start_of_utc_day(now)
    window_start = _parse_rfc3339(key_row.get("daily_window_start_at")) if isinstance(key_row.get("daily_window_start_at"), str) else None
    if window_start is None or _start_of_utc_day(window_start) < day0:
        key_row["daily_window_start_at"] = _iso(day0)
        key_row["daily_requests_used"] = 0
        key_row["updated_at"] = _iso(now)

    used = int(key_row.get("daily_requests_used") or 0)
    limit = int(key_row.get("daily_request_limit") or 0)
    if used + 1 > limit:
        _audit_call(key_row, False, "get_search_request", t0, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_requests_used=used)

    key_row["daily_requests_used"] = used + 1
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    for i, kk in enumerate(keys):
        if kk.get("id") == key_row.get("id"):
            keys[i] = key_row
            break
    _save("api_keys.json", keys)

    reqs = _load("search_requests.json")
    sr = None
    for r in reqs:
        if isinstance(r, dict) and not r.get("is_audit") and r.get("id") == search_request_id.strip():
            sr = r
            break
    if sr is None:
        _audit_call(key_row, True, "get_search_request", t0, "OK")
        return _err("NOT_FOUND", "search_request_id not found")

    if sr.get("api_key_id") != key_row.get("id"):
        _audit_call(key_row, True, "get_search_request", t0, "OK")
        return _err("UNAUTHORIZED", "Search request is not owned by this API key")

    # Add summary counts (computed live)
    results = _load("search_results.json")
    num_results = sum(1 for rr in results if isinstance(rr, dict) and rr.get("search_request_id") == sr.get("id"))
    out = dict(sr)
    out["num_results_returned_live"] = num_results

    _audit_call(key_row, True, "get_search_request", t0, "OK")
    return {"data": out}

