        return _err("UNAUTHORIZED", "Invalid API key or key not active")

    # Quota consume
    now = _now_utc()
    day0 = _start_of_utc_day(now)
    window_start = _parse_rfc3339(key_row.get("daily_window_start_at")) if isinstance(key_row.get("daily_window_start_at"), str) else None
    if window_start is None or _start_of_utc_day(window_start) < day0:
        key_row["daily_window_start_at"] = _iso(day0)
        key_row["daily_requests_used"] = 0
        key_row["updated_at"] = _iso(now)

    used = int(key_row.get("daily_requests_used") or 0)
    limit = int(key_row.get("daily_request_limit") or 0)
    if used + 1 > limit:
        _audit_call(key_row, False, "list_search_results", t0, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", daily_request_limit=limit, daily_requests_used=used)

    key_row["daily_requests_used"] = used + 1
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    for i, kk in enumerate(keys):
        if kk.get("id") == key_row.get("id"):
            keys[i] = key_row
            break
    _save("api_keys.json", keys)

    # ownership check
    reqs = _load("search_requests.json")
    sr = None
    for r in reqs:
        if isinstance(r, dict) and not r.get("is_audit") and r.get("id") == search_request_id.strip():
            sr = r
            break
    if sr is None:
        _audit_call(key_row, True, "list_search_results", t0, "OK")
        return _err("NOT_FOUND", "search_request_id not found")
    if sr.get("api_key_id") != key_row.get("id"):
        _audit_call(key_row, True, "list_search_results", t0, "OK")
        return _err("UNAUTHORIZED", "Search request is not owned by this API key")

    results = _load("search_results.json")
    pubs = _load("publications.json")
    pub_by_id = {p.get("id"): p for p in pubs if isinstance(p, dict) and p.get("id")}

    rows = [rr for rr in results if isinstance(rr, dict) and rr.get("search_request_id") == sr.get("id")]
    if result_type is not None:
        rows = [rr for rr in rows if rr.get("result_type") == result_type]

    # order by rank asc
    rows.sort(key=lambda rr: (int(rr.get("rank") or 0), rr.get("id") or ""))

    start_rank = None
    start_idx = 0
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token.strip():
            _audit_call(key_row, True, "list_search_results", t0, "OK")
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")
        tok = None
        try:
            tok = _b64d(page_token.strip())
        except Exception:
            _audit_call(key_row, True, "list_search_results", t0, "OK")
            return _err("VALIDATION_ERROR", "Invalid page_token")
        if not isinstance(tok, dict) or tok.get("v") != 1 or tok.get("rank") is None:
            _audit_call(key_row, True, "list_search_results", t0, "OK")
            return _err("VALIDATION_ERROR", "Invalid page_token payload")
        if not isinstance(tok.get("rank"), int) or tok["rank"] < 1:
            _audit_call(key_row, True, "list_search_results", t0, "OK")
            return _err("VALIDATION_ERROR", "Invalid page_token rank")
        start_rank = tok["rank"]
        # find first row with rank > start_rank
        for i, rr in enumerate(rows):
            if int(rr.get("rank") or 0) > start_rank:
                start_idx = i
                break
        else:
            start_idx = len(rows)

    page = rows[start_idx:start_idx + page_size]
    out_items = []
    for rr in page:
        pub = pub_by_id.get(rr.get("publication_id"))
        out_items.append({
            "id": rr.get("id"),
            "search_request_id": rr.get("search_request_id"),
            "publication_id": rr.get("publication_id"),
            "rank": rr.get("rank"),
            "result_type": rr.get("result_type"),
            "snippet": rr.get("snippet"),
            "captured_at": rr.get("captured_at"),
            "publication": pub,
        })

    total = len(rows)
    if page:
        last_rank = int(page[-1].get("rank") or 0)
    else:
        last_rank = start_rank if start_rank is not None else 0

    # has_more if there exists an item with rank > last_rank in filtered set
    has_more = any(int(rr.get("rank") or 0) > last_rank for rr in rows)
    next_token = _b64e({"v": 1, "rank": last_rank}) if has_more and last_rank > 0 else None

    _audit_call(key_row, True, "list_search_results", t0, "OK")
    return {
        "data": out_items,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
        },
    }

def cancel_search_request(api_key, search_request_id, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0128000" if __import__("os").path.isdir("./environment_mix/0128000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        t = s.strip()
        if not t:
            return None
        try:
            if t.endswith("Z"):
                return datetime.datetime.fromisoformat(t[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _start_of_utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    def _authenticate_active_api_key(api_key_value, api_keys_rows):
        # Authenticate against client-visible id only (store has no plaintext keys).
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for k in api_keys_rows:
            if isinstance(k, dict) and k.get("id") == v and k.get("status") == "active":
                return k
        return None

    def _reset_daily_window_if_needed(key_row, now_dt):
        # When daily_window_start_at is before current UTC day, reset.
        start = _parse_dt(key_row.get("daily_window_start_at"))
        sod = _start_of_utc_day(now_dt)
        if start is None or start < sod:
            key_row["daily_window_start_at"] = _iso(sod)
            key_row["daily_requests_used"] = 0

    def _increment_quota_or_reject(key_row):
        try:
            limit = int(key_row.get("daily_request_limit", 0))
            used = int(key_row.get("daily_requests_used", 0))
        except Exception:
            return False, _err("VALIDATION_ERROR", "API key quota fields are invalid.")
        if limit < 0 or used < 0:
            return False, _err("VALIDATION_ERROR", "API key quota fields violate constraints.")
        if used + 1 > limit:
            return False, _err("QUOTA_EXCEEDED", "Daily request limit exceeded for this API key.")
        key_row["daily_requests_used"] = used + 1
        return True, None

    def _log_request(log_rows, api_key_id, status, latency_ms, error_code=None, message=None):
        # No dedicated request-log collection exists in schema; record to search_requests as business events only.
        # This function is kept for clarity but does not persist logs elsewhere.
        return

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string.")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string if provided.")
    reason_clean = reason.strip() if isinstance(reason, str) and reason.strip() else None

    t0 = time.time()

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    key_row = _authenticate_active_api_key(api_key, api_keys)
    if key_row is None:
        # Must be active; suspended/revoked are unauthorized for tool use.
        return _err("UNAUTHORIZED", "API key is invalid or not active.")

    now_dt = _now()

    # Enforce and increment quota for every accepted tool call (i.e., authenticated call).
    _reset_daily_window_if_needed(key_row, now_dt)
    ok, qerr = _increment_quota_or_reject(key_row)
    if not ok:
        return qerr

    # Persist quota increment immediately (best-effort atomicity in JSON store)
    key_row["updated_at"] = _iso(now_dt)
    key_row["last_used_at"] = _iso(now_dt)
    _save("api_keys.json", api_keys)

    # Load requests and locate target
    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []

    srq = None
    for r in search_requests:
        if isinstance(r, dict) and r.get("id") == search_request_id.strip():
            srq = r
            break
    if srq is None:
        return _err("NOT_FOUND", "Search request not found.")

    # Ownership: must be owned by the calling API key
    if srq.get("api_key_id") != key_row.get("id"):
        return _err(
            "UNAUTHORIZED",
            "Search request is not owned by this API key (business rule: cancellation allowed only for owner)."
        )

    # Transition rule: only queued or running can be cancelled
    status = srq.get("status")
    if status not in ("queued", "running"):
        return _err(
            "INVALID_TRANSITION",
            f"Cannot cancel a search request in status '{status}'. Only 'queued' or 'running' may transition to 'cancelled'."
        )

    # Apply transition
    srq["status"] = "cancelled"
    srq["finished_at"] = _iso(now_dt)
    srq["updated_at"] = _iso(now_dt)
    # Store cancellation diagnostics in error fields (schema has no dedicated cancel reason field)
    if reason_clean:
        srq["error_code"] = "CANCELLED"
        srq["error_message"] = reason_clean
    else:
        srq["error_code"] = "CANCELLED"
        srq["error_message"] = srq.get("error_message") or "Cancelled by user."

    _save("search_requests.json", search_requests)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "search_request": srq,
        "meta": {
            "latency_ms": latency_ms
        }
    }

def refresh_author_profile(api_key, author_profile_id, force=None, **_extra):
    import json, os, datetime, time, random, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0128000" if __import__("os").path.isdir("./environment_mix/0128000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day_start(dt):
        return datetime.datetime(dt.year, dt.month, dt.day)

    def _normalize_name(name):
        if name is None:
            return ""
        if not isinstance(name, str):
            return ""
        s = name.strip().lower()
        s = re.sub(r"\s+", " ", s)
        s = re.sub(r"[^\w\s\-\.\']", "", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _normalize_title(title):
        if title is None:
            return ""
        if not isinstance(title, str):
            return ""
        s = title.strip().lower()
        s = re.sub(r"\s+", " ", s)
        s = re.sub(r"[^\w\s]", "", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randrange(100000, 999999)}"

    def _log_call(status, api_key_id=None, error_code=None, error_message=None, latency_ms=None):
        # Best-effort request logging if the service has a log collection; schema does not declare one.
        # Implement as no-op if file absent; do not create new undeclared collections.
        return

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log_call("failed", None, "VALIDATION_ERROR", "api_key must be a non-empty string", int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(author_profile_id, str) or not author_profile_id.strip():
        _log_call("failed", None, "VALIDATION_ERROR", "author_profile_id must be a non-empty string", int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "author_profile_id must be a non-empty string")
    if force is None:
        force = False
    if not isinstance(force, bool):
        _log_call("failed", None, "VALIDATION_ERROR", "force must be a boolean", int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "force must be a boolean")

    api_keys = _load("api_keys.json")
    author_profiles = _load("author_profiles.json")
    publications = _load("publications.json")
    author_pubs = _load("author_publications.json")

    # Authenticate: must match client-visible api_key by id OR key_hash (no hashing of provided key)
    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_hash") == api_key:
            key_row = r
            break
    if not key_row:
        _log_call("failed", None, "UNAUTHORIZED", "Invalid API key", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        _log_call("failed", key_row.get("id"), "UNAUTHORIZED", "API key not active", int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "API key not active")

    # Quota enforcement: reset daily window if needed; then attempt atomic increment.
    now_dt = datetime.datetime.utcnow()
    dws = _parse_dt(key_row.get("daily_window_start_at"))
    if dws is None:
        dws = _utc_day_start(now_dt)
        key_row["daily_window_start_at"] = dws.replace(microsecond=0).isoformat() + "Z"
        key_row["daily_requests_used"] = 0

    # If window is before current UTC day start, reset
    today_start = _utc_day_start(now_dt)
    if dws < today_start:
        key_row["daily_window_start_at"] = today_start.replace(microsecond=0).isoformat() + "Z"
        key_row["daily_requests_used"] = 0

    used = key_row.get("daily_requests_used")
    limit = key_row.get("daily_request_limit")
    if not isinstance(used, int) or used < 0:
        _log_call("failed", key_row.get("id"), "VALIDATION_ERROR", "API key quota counter invalid", int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "API key quota counter invalid")
    if not isinstance(limit, int) or limit < 0:
        _log_call("failed", key_row.get("id"), "VALIDATION_ERROR", "API key quota limit invalid", int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "API key quota limit invalid")

    if used + 1 > limit:
        # Persist window reset if it happened, but do not increment used.
        key_row["updated_at"] = _now()
        _save("api_keys.json", api_keys)
        _log_call("failed", key_row.get("id"), "QUOTA_EXCEEDED", "Daily request limit exceeded", int((time.time() - t0) * 1000))
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", limit=limit, used=used)

    # Apply the increment and persist immediately to approximate atomicity in this single-process store.
    key_row["daily_requests_used"] = used + 1
    key_row["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    # Locate author profile
    prof = None
    for r in author_profiles:
        if isinstance(r, dict) and r.get("id") == author_profile_id:
            prof = r
            break
    if not prof:
        _log_call("failed", key_row.get("id"), "NOT_FOUND", "Author profile not found", int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "Author profile not found")

    # Caching behavior: if not force and recently fetched, short-circuit.
    # Define "recent" as within last 24 hours.
    last_fetched = _parse_dt(prof.get("last_fetched_at"))
    if (not force) and last_fetched is not None:
        age = (now_dt - last_fetched).total_seconds()
        if age >= 0 and age < 24 * 3600:
            # Return current record and publications on record
            ap_rows = [j for j in author_pubs if isinstance(j, dict) and j.get("author_profile_id") == prof.get("id")]
            pub_map = {p.get("id"): p for p in publications if isinstance(p, dict) and p.get("id") is not None}
            pubs = []
            for j in sorted(ap_rows, key=lambda x: (x.get("sort_order") is None, x.get("sort_order") or 10**9, x.get("id") or "")):
                p = pub_map.get(j.get("publication_id"))
                if p:
                    pubs.append({"publication": p, "author_publication": j})
            prof_out = dict(prof)
            _log_call("succeeded", key_row.get("id"), None, None, int((time.time() - t0) * 1000))
            return {
                "author_profile": prof_out,
                "publications": pubs,
                "cached": True,
                "quota": {"daily_limit": limit, "daily_used": key_row.get("daily_requests_used"), "daily_window_start_at": key_row.get("daily_window_start_at")},
            }

    # Simulated fetch outcome (offline service): deterministically decide based on profile content
    # - If profile is currently blocked, keep blocked (still blocked)
    # - If status is not_found and force, allow it to become active with low probability unless name suggests missing
    # - If normalized_name contains "captcha" or "blocked", treat as blocked
    # - If normalized_name contains "unknown" or "not found", treat as not_found
    norm_name = prof.get("normalized_name")
    if not isinstance(norm_name, str) or not norm_name.strip():
        # Fix invariant
        norm_name = _normalize_name(prof.get("display_name") or "")
        prof["normalized_name"] = norm_name

    outcome = "active"
    if isinstance(norm_name, str):
        if "captcha" in norm_name or "blocked" in norm_name:
            outcome = "blocked"
        elif "unknown" in norm_name or "not found" in norm_name or "notfound" in norm_name:
            outcome = "not_found"
        else:
            # If previously blocked, remain blocked unless force and deterministic hash says recover
            if prof.get("status") == "blocked":
                h = int(hashlib.sha256((prof.get("id", "") + norm_name).encode("utf-8")).hexdigest(), 16)
                outcome = "active" if (force and (h % 5 == 0)) else "blocked"
            elif prof.get("status") == "not_found":
                h = int(hashlib.sha256((prof.get("id", "") + norm_name).encode("utf-8")).hexdigest(), 16)
                outcome = "active" if (force and (h % 7 == 0)) else "not_found"
            else:
                outcome = "active"

    # Apply lifecycle transitions per declared rules
    allowed = {
        "active": {"stale", "blocked"},
        "stale": {"active", "not_found", "blocked"},
        "not_found": {"active", "blocked"},
        "blocked": {"active", "stale"},
    }
    current_status = prof.get("status")
    if current_status not in allowed:
        current_status = "stale"
        prof["status"] = current_status

    # Determine target status mapping
    target_status = outcome
    # If outcome is not_found and current is active, must pass through stale first (active -> stale allowed, stale -> not_found allowed)
    transitions_applied = []
    if current_status == "active" and target_status == "not_found":
        prof["status"] = "stale"
        transitions_applied.append(("active", "stale"))
        current_status = "stale"

    if prof.get("status") != target_status:
        if target_status not in allowed.get(prof.get("status"), set()):
            _log_call("failed", key_row.get("id"), "INVALID_TRANSITION", "Illegal author profile status transition", int((time.time() - t0) * 1000))
            return _err(
                "INVALID_TRANSITION",
                "Illegal author profile status transition",
                from_status=prof.get("status"),
                to_status=target_status,
            )
        transitions_applied.append((prof.get("status"), target_status))
        prof["status"] = target_status

    # Update fetched timestamp rules:
    # - If blocked: do not overwrite last_fetched_at with a successful timestamp.
    # - If active or not_found: set last_fetched_at to now (represents fetch attempt completing)
    if target_status != "blocked":
        prof["last_fetched_at"] = _now()

    prof["updated_at"] = _now()

    # Refresh publications list:
    # Only if not blocked. If not_found, clear associations (represents no publications visible).
    # If active, generate/update a small deterministic set of publications.
    if target_status == "blocked":
        # Do not change associations
        pass
    else:
        # Remove existing join rows for this author (refresh)
        before_len = len(author_pubs)
        author_pubs = [j for j in author_pubs if not (isinstance(j, dict) and j.get("author_profile_id") == prof.get("id"))]
        # If not_found: keep empty
        if target_status == "active":
            # Create deterministic publications based on normalized name
            seed = int(hashlib.sha256(norm_name.encode("utf-8")).hexdigest(), 16)
            k = 5 + (seed % 6)  # 5-10 pubs
            created_pub_ids = []
            now_iso = _now()
            for i in range(k):
                year = 2010 + ((seed // (i + 1)) % 15)
                title = f"Selected Works of {prof.get('display_name')}: Paper {i+1}"
                norm_title = _normalize_title(title)
                # scholar_cluster_id optional; create one for stable dedupe
                cluster = f"cluster_{(seed // (i + 3)) % 10000000}"
                # Deduplicate preferentially by scholar_cluster_id among active publications
                pub = None
                for p in publications:
                    if not isinstance(p, dict):
                        continue
                    if p.get("scholar_cluster_id") == cluster and p.get("status") == "active":
                        pub = p
                        break
                if pub is None:
                    pub_id = _new_id("pub")
                    pub = {
                        "id": pub_id,
                        "scholar_cluster_id": cluster,
                        "title": title,
                        "normalized_title": norm_title,
                        "publication_year": int(year),
                        "venue": None,
                        "authors_text": prof.get("display_name"),
                        "abstract_snippet": None,
                        "url": None,
                        "pdf_url": None,
                        "cited_by_count": 0,
                        "status": "active",
                        "merged_into_publication_id": None,
                        "last_seen_at": now_iso,
                        "created_at": now_iso,
                        "updated_at": now_iso,
                    }
                    publications.append(pub)
                else:
                    # Refresh last_seen_at
                    pub["last_seen_at"] = now_iso
                    pub["updated_at"] = now_iso
                created_pub_ids.append(pub["id"])
                # Add join row (unique(author_profile_id, publication_id))
                j_id = _new_id("apub")
                join = {
                    "id": j_id,
                    "author_profile_id": prof.get("id"),
                    "publication_id": pub["id"],
                    "authorship_position": None,
                    "is_corresponding": False,
                    "sort_order": i + 1,
                    "added_at": now_iso,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                author_pubs.append(join)

        # Persist join/publications update
        _save("author_publications.json", author_pubs)
        _save("publications.json", publications)

    # Persist author profile update
    _save("author_profiles.json", author_profiles)

    # Return updated profile and its publications on record
    ap_rows = [j for j in author_pubs if isinstance(j, dict) and j.get("author_profile_id") == prof.get("id")]
    pub_map = {p.get("id"): p for p in publications if isinstance(p, dict) and p.get("id") is not None}
    pubs = []
    for j in sorted(ap_rows, key=lambda x: (x.get("sort_order") is None, x.get("sort_order") or 10**9, x.get("id") or "")):
        p = pub_map.get(j.get("publication_id"))
        if p:
            pubs.append({"publication": p, "author_publication": j})

    # Update key last_used_at only on successful accepted call (this one)
    key_row["last_used_at"] = _now()
    key_row["updated_at"] = _now()
    _save("api_keys.json", api_keys)

    _log_call("succeeded", key_row.get("id"), None, None, int((time.time() - t0) * 1000))
    return {
        "author_profile": dict(prof),
        "publications": pubs,
        "cached": False,
        "transitions": transitions_applied,
        "quota": {"daily_limit": limit, "daily_used": key_row.get("daily_requests_used"), "daily_window_start_at": key_row.get("daily_window_start_at")},
    }
